public class OrderAggregate {
    private final OrderId id;
    private OrderStatus status;
    private final List<OrderLineItem> items;
    private final List<DomainEvent> domainEvents = new ArrayList<>();

    public OrderAggregate(OrderId id, List<OrderLineItem> items) {
        if (items == null || items.isEmpty()) {
            throw new IllegalArgumentException("An order must contain at least one item.");
        }
        this.id = id;
        this.items = new ArrayList<>(items);
        this.status = OrderStatus.PENDING;
    }

    public void cancel(String reason) {
        // Invariant: Cannot cancel already dispatched order
        if (this.status == OrderStatus.SHIPPED || this.status == OrderStatus.DELIVERED) {
            throw new IllegalStateException("Cannot cancel an order that has already shipped.");
        }
        this.status = OrderStatus.CANCELLED;
        this.domainEvents.add(new OrderCancelledEvent(this.id, reason, Instant.now()));
    }

    public List<DomainEvent> pollEvents() {
        List<DomainEvent> events = new ArrayList<>(this.domainEvents);
        this.domainEvents.clear();
        return events;
    }
}

