func DeadlinePropagationMiddleware(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        // Default max budget: 2000ms
        budget := 2000 * time.Millisecond

        if deadlineHeader := r.Header.Get("X-Client-Timeout-Budget-Ms"); deadlineHeader != "" {
            if ms, err := strconv.ParseInt(deadlineHeader, 10, 64); err == nil && ms > 0 {
                budget = time.Duration(ms) * time.Millisecond
            }
        }

        ctx, cancel := context.WithTimeout(r.Context(), budget)
        defer cancel()

        // Fail fast if already expired
        if ctx.Err() != nil {
            http.Error(w, "Gateway Timeout: Deadline already expired", http.StatusGatewayTimeout)
            return
        }

        next.ServeHTTP(w, r.WithContext(ctx))
    })
}

export interface RetryConfig {
  maxAttempts: number;
  baseMs: number;
  capMs: number;
}

export async function executeWithFullJitter<T>(
  fn: () => Promise<T>,
  config: RetryConfig = { maxAttempts: 3, baseMs: 100, capMs: 2000 }
): Promise<T> {
  let attempt = 0;

  while (true) {
    try {
      return await fn();
    } catch (error: any) {
      attempt++;
      if (attempt >= config.maxAttempts || !isTransientError(error)) {
        throw error;
      }

      // Amazon Full Jitter Formula: rand(0, min(cap, base * 2^attempt))
      const exponentialMax = Math.min(config.capMs, config.baseMs * Math.pow(2, attempt));
      const jitterSleepMs = Math.floor(Math.random() * exponentialMax);

      console.warn(`Attempt ${attempt} failed. Retrying in ${jitterSleepMs}ms...`);
      await new Promise((resolve) => setTimeout(resolve, jitterSleepMs));
    }
  }
}

function isTransientError(error: any): boolean {
  const status = error?.response?.status;
  return status === 503 || status === 504 || status === 429 || error.code === 'ECONNRESET';
}

