type ResilientConsumer struct {
    reader *kafka.Reader
    dlqWriter *kafka.Writer
}

func (c *ResilientConsumer) ProcessMessage(ctx context.Context, msg kafka.Message) {
    const maxRetries = 3
    var err error

    for attempt := 1; attempt <= maxRetries; attempt++ {
        err = executeBusinessLogic(msg.Value)
        if err == nil {
            c.reader.CommitMessages(ctx, msg)
            return
        }
        time.Sleep(time.Duration(attempt * 100) * time.Millisecond)
    }

    // Retries exhausted: Route Poison Pill to DLQ
    dlqMsg := kafka.Message{
        Key:   msg.Key,
        Value: msg.Value,
        Headers: []kafka.Header{
            {Key: "X-Original-Topic", Value: []byte(msg.Topic)},
            {Key: "X-Error-Message", Value: []byte(err.Error())},
            {Key: "X-Failed-Timestamp", Value: []byte(time.Now().Format(time.RFC3339))},
        },
    }
    c.dlqWriter.WriteMessages(ctx, dlqMsg)
    c.reader.CommitMessages(ctx, msg) // Advance primary partition offset!
}

