export interface DomainEvent {
  type: string;
  occurredAt: string;
  payload: any;
}

export class OrderAggregate {
  id: string = '';
  status: string = 'CREATED';
  totalCents: number = 0;
  version: number = 0;

  // Rehydrate state from event history
  static fromHistory(events: DomainEvent[]): OrderAggregate {
    const aggregate = new OrderAggregate();
    for (const event of events) {
      aggregate.apply(event);
      aggregate.version++;
    }
    return aggregate;
  }

  private apply(event: DomainEvent): void {
    switch (event.type) {
      case 'OrderCreated':
        this.id = event.payload.orderId;
        this.totalCents = event.payload.totalCents;
        this.status = 'PENDING';
        break;
      case 'OrderPaid':
        this.status = 'PAID';
        break;
      case 'OrderCancelled':
        this.status = 'CANCELLED';
        break;
    }
  }
}

export async function handleVersionedEvent(
  event: { aggregateId: string; version: number; payload: any },
  db: any,
  redis: any
) {
  const currentVersion = await db.getVersion(event.aggregateId);

  // Case 1: Exact expected next version
  if (event.version === currentVersion + 1) {
    await db.applyMutation(event.aggregateId, event.payload, event.version);
    await drainBufferedEvents(event.aggregateId, event.version, db, redis);
    return;
  }

  // Case 2: Stale duplicate event (already processed)
  if (event.version <= currentVersion) {
    console.warn(`Ignoring stale event v${event.version} (current: v${currentVersion})`);
    return;
  }

  // Case 3: Future event (Gap detected! Buffer in Redis)
  console.warn(`Gap detected! Received v${event.version}, expected v${currentVersion + 1}. Buffering...`);
  await redis.zadd(
    `buffer:${event.aggregateId}`,
    event.version,
    JSON.stringify(event)
  );
}

