)

func ExecuteTracedOperation(ctx context.Context, orderId string) error {
    tracer := otel.GetTracerProvider().Tracer("order-service")

    // Start child span linked to parent trace context
    ctx, span := tracer.Start(ctx, "ProcessOrderDatabaseCommit",
        trace.WithSpanKind(trace.SpanKindInternal),
    )
    defer span.End()

    span.SetAttributes(
        attribute.String("order.id", orderId),
        attribute.String("db.system", "postgresql"),
    )

    if err := executeDatabaseCommit(ctx, orderId); err != nil {
        span.RecordError(err)
        span.SetStatus(codes.Error, err.Error())
        return err
    }

    span.SetStatus(codes.Ok, "Database commit successful")
    return nil
}
